DROP TABLE IF EXISTS `messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `messages` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `recipient_profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `sender_profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci DEFAULT NULL,
  `message_type` varchar(32) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT 'player',
  `title` varchar(120) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `body` text COLLATE utf8mb4_hungarian_ci NOT NULL,
  `payload_json` longtext COLLATE utf8mb4_hungarian_ci NOT NULL,
  `read_at` bigint DEFAULT NULL,
  `created_at` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_messages_recipient_created` (`recipient_profile_name`,`created_at` DESC),
  KEY `idx_messages_recipient_unread` (`recipient_profile_name`,`read_at`,`created_at` DESC),
  KEY `fk_messages_sender` (`sender_profile_name`),
  CONSTRAINT `fk_messages_recipient` FOREIGN KEY (`recipient_profile_name`) REFERENCES `players` (`profile_name`) ON DELETE CASCADE,
  CONSTRAINT `fk_messages_sender` FOREIGN KEY (`sender_profile_name`) REFERENCES `players` (`profile_name`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_hungarian_ci;
