INSERT INTO `messages` VALUES (8,'linda','lind','player','Üzenet érkezett: lind','szia itt vagyokl részegen','{}',1783876979882,1783876968904),(14,'indian','linda','player','Lezárult a tagságod a linda családban','linda döntése alapján többé nem vagy a linda család tagja. Az ajtó bezárult, az utca azonban továbbra is nyitva áll előtted.','{\"kind\":\"clan_membership_removed\",\"clanId\":\"clan-mrj9keec-linda\",\"clanName\":\"linda\"}',1784052275778,1784052260577),(15,'indian','linda','player','Egy szék vár rád a linda asztalánál','linda üzenete: a linda család felfigyelt rád. Ha elfogadod a meghívást, helyet kapsz az asztalnál — de ne feledd: a családba belépni döntés, a hűség pedig eskü.','{\"kind\": \"clan_invitation\", \"clanId\": \"clan-mrj9keec-linda\", \"clanName\": \"linda\", \"expiresAt\": 1784657064132, \"invitedBy\": \"linda\", \"invitationId\": 4, \"invitationStatus\": \"accepted\"}',1784052275778,1784052264132),(16,'linda','indian','player','Üzenet érkezett: indian','köszönöm szépen a meghivást','{}',1784052322259,1784052308669);
/*!40000 ALTER TABLE `messages` ENABLE KEYS */;
UNLOCK TABLES;

