  `profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `action_type` varchar(32) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `action_status` varchar(24) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT 'active',
  `payload_json` longtext COLLATE utf8mb4_hungarian_ci NOT NULL,
  `created_at` bigint NOT NULL,
  `updated_at` bigint NOT NULL,
  `expires_at` bigint NOT NULL,
  PRIMARY KEY (`action_id`),
  KEY `idx_action_sessions_profile_active` (`profile_name`,`action_type`,`action_status`,`updated_at` DESC),
  KEY `idx_action_sessions_expiry` (`action_status`,`expires_at`),
  CONSTRAINT `fk_action_sessions_player` FOREIGN KEY (`profile_name`) REFERENCES `players` (`profile_name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_hungarian_ci;
