--
-- Table structure for table `player_districts`
--

DROP TABLE IF EXISTS `player_districts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_districts` (
  `profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `district_id` varchar(64) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `slot_index` int NOT NULL DEFAULT '0',
  `is_selected` tinyint(1) NOT NULL DEFAULT '0',
  `payload_json` longtext COLLATE utf8mb4_hungarian_ci NOT NULL,
  `updated_at` bigint NOT NULL,
  PRIMARY KEY (`profile_name`,`district_id`),
  KEY `idx_player_districts_profile` (`profile_name`,`slot_index`,`updated_at` DESC),
  CONSTRAINT `fk_player_districts_player` FOREIGN KEY (`profile_name`) REFERENCES `players` (`profile_name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_hungarian_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

